MODULOS = ("taller", "caja_chica")
ACCIONES = ("puede_crear", "puede_leer", "puede_actualizar", "puede_eliminar")
PREFIJO = "Permisos - "


def pasar_a_sucursales(apps, schema_editor):
    """Taller y Caja chica ahora se asignan por sucursal. Quien ya tenia el
    permiso lo conserva en cada una de sus sucursales asignadas."""
    from django.conf import settings

    RolPermiso = apps.get_model("usuarios", "RolPermiso")
    UsuarioSucursal = apps.get_model("usuarios", "UsuarioSucursal")
    UsuarioModuloSucursal = apps.get_model("usuarios", "UsuarioModuloSucursal")
    app_label, model_name = settings.AUTH_USER_MODEL.split(".")
    User = apps.get_model(app_label, model_name)

    permisos = RolPermiso.objects.filter(modulo__in=MODULOS, rol__es_personalizado=True).select_related("rol")
    for permiso in permisos:
        flags = {accion: bool(getattr(permiso, accion)) for accion in ACCIONES}
        if not any(flags.values()):
            continue
        nombre = str(permiso.rol.nombre or "")
        if not nombre.startswith(PREFIJO):
            continue
        email = nombre[len(PREFIJO):].strip()
        user = User.objects.filter(email__iexact=email).first()
        if user is None:
            continue
        for sucursal_id in UsuarioSucursal.objects.filter(usuario_id=user.id).values_list("sucursal_id", flat=True):
            UsuarioModuloSucursal.objects.get_or_create(
                usuario_id=user.id, modulo=permiso.modulo, sucursal_id=sucursal_id, defaults=flags
            )


